import matplotlib.pyplot as plt
import numpy as np
from Bio import Align
import matplotlib.patches as patches

# Define sequences (extracted from the Sequence Catalog files)
sequences = {
    'Human_MMP2': '',
    'Mouse_MMP2': '',
    'Human_MMP9': '',
    'Human_ADAM17': '',
    'Rat_ADAM17': ''
}

# Domain definitions (Residue ranges)
domains = {
    'MMP9': [
        (1, 19, 'Signal', '#D1C4E9'),
        (20, 93, 'Pro-domain', '#C5CAE9'),
        (107, 444, 'Catalytic (incl. Fibronectin)', '#BBDEFB'),
        (217, 390, 'Fibronectin II', '#81C784'),
        (512, 707, 'Hemopexin', '#FFECB3')
    ],
    'MMP2': [
        (1, 29, 'Signal', '#D1C4E9'),
        (30, 109, 'Pro-domain', '#C5CAE9'),
        (110, 445, 'Catalytic (incl. Fibronectin)', '#BBDEFB'),
        (218, 391, 'Fibronectin II', '#81C784'),
        (461, 660, 'Hemopexin', '#FFECB3')
    ],
    'ADAM17': [
        (1, 17, 'Signal', '#D1C4E9'),
        (18, 214, 'Pro-domain', '#C5CAE9'),
        (215, 474, 'Catalytic', '#BBDEFB'),
        (475, 562, 'Disintegrin', '#F8BBD0'),
        (563, 671, 'Cys-rich', '#E1BEE7'),
        (705, 725, 'Transmembrane', '#FFCCBC'),
        (726, 824, 'Cytoplasmic', '#CFD8DC')
    ]
}

def plot_manufacturer_alignment(full_seq, construct_range, protein_name, manufacturer, filename):
    # Parse range (e.g., "Phe107-Pro449")
    # For simplicity, we'll use numeric indices provided in the prompt/metadata
    start_res, end_res = construct_range
    
    length = len(full_seq)
    
    fig, ax = plt.subplots(figsize=(16, 6))
    
    # 1. Draw Domain boxes for Full Sequence
    y_full = 3
    ax.text(-10, y_full + 0.4, "Full Sequence", fontweight='bold', va='center', ha='right')
    ax.add_patch(patches.Rectangle((0, y_full), length, 0.5, color='#EEEEEE', alpha=0.5)) # Background bar
    
    protein_type = protein_name.split()[0] # e.g., "MMP9"
    for start, end, label, color in domains.get(protein_type, []):
        width = end - start + 1
        rect = patches.Rectangle((start-1, y_full), width, 0.5, color=color, label=label)
        ax.add_patch(rect)
        # Add label text above the box
        ax.text(start + width/2, y_full + 0.6, label, rotation=45, ha='left', va='bottom', fontsize=9)

    # 2. Draw Manufacturer Construct
    y_const = 1
    ax.text(-10, y_const + 0.4, f"{manufacturer} Construct", fontweight='bold', va='center', ha='right')
    ax.add_patch(patches.Rectangle((0, y_const), length, 0.5, color='#EEEEEE', alpha=0.3)) # Background bar
    
    # Highlight the range
    const_width = end_res - start_res + 1
    ax.add_patch(patches.Rectangle((start_res-1, y_const), const_width, 0.5, color='#FF9800', alpha=0.8))
    
    # Add ticks and labels
    ax.set_xlim(-50, length + 50)
    ax.set_ylim(0, 6)
    ax.set_yticks([])
    ax.set_xlabel("Residue Position")
    ax.set_title(f"{protein_name}: Domain Architecture vs. {manufacturer} Construct", pad=40, fontsize=14)
    
    # Grid and spikes
    ax.axvline(start_res-1, color='red', linestyle='--', alpha=0.5)
    ax.axvline(end_res-1, color='red', linestyle='--', alpha=0.5)
    ax.text(start_res, y_const - 0.3, f"Start: {start_res}", color='red', ha='center')
    ax.text(end_res, y_const - 0.3, f"End: {end_res}", color='red', ha='center')

    plt.tight_layout()
    plt.savefig(filename, dpi=300)
    plt.close()

# Alignment data based on Domain_Architecture.csv
# MMP9 Human: Enzo (107-449)
plot_manufacturer_alignment(sequences['Human_MMP9'], (107, 449), 'Human MMP9', 'Enzo', 'MMP9_Enzo_Domains.png')

# MMP2 Human: Enzo (110-452)
plot_manufacturer_alignment(sequences['Human_MMP2'], (110, 452), 'Human MMP2', 'Enzo', 'MMP2_Enzo_Domains.png')

# MMP2 Mouse: Sino (409-662)
plot_manufacturer_alignment(sequences['Mouse_MMP2'], (409, 662), 'Mouse MMP2', 'Sino Biological', 'MMP2_Sino_Domains.png')

# ADAM17 Human: Enzo (18-477)
plot_manufacturer_alignment(sequences['Human_ADAM17'], (18, 477), 'Human ADAM17', 'Enzo', 'ADAM17_Enzo_Domains.png')

# ADAM17 Rat: Sino (1-563)
plot_manufacturer_alignment(sequences['Rat_ADAM17'], (1, 563), 'Rat ADAM17', 'Sino Biological', 'ADAM17_Sino_Domains.png')

print("Manufacturer-specific domain alignment diagrams generated.")
